def transform(grid):
    out = [row[:] for row in grid]
    for r in range(len(out)):
        out[r][-1] = 8
    return out

def transform(grid):
    out = [row[:] for row in grid]
    if any(2 in row for row in grid):
        for r in range(len(out)):
            out[r][-1] = 8
    return out

def transform(grid):
    out = [row[:] for row in grid]
    has_run = False
    for row in grid:
        for c in range(len(row)-1):
            if row[c] == 2 and row[c+1] == 2:
                has_run = True
    if has_run:
        for r in range(len(out)):
            out[r][-1] = 8
    return out
